import React from 'react';
import { Link } from 'react-router-dom';
import { FiHome, FiAlignLeft, FiCheck, FiLayers, FiBookOpen, FiChevronDown, FiSearch } from 'react-icons/fi';
import Seo from '../components/Seo';
import Art from '../components/Art';
import './RmsLanding.css';

// The public RMS page. Every drawn screen below imitates the real RMS app (requirements, trace, verification,
// baselines, agent connections, exchange) with neutral example content for a pump controller.

const Pill = ({ tone = 'muted', children }) => <span className="rl-pill" data-tone={tone}><i />{children}</span>;
const Chip = ({ on, n, children }) => <span className="rl-chip" data-on={on || undefined}>{children}{n !== undefined && <b>{n}</b>}</span>;
const Id = ({ children }) => <span className="rl-id">{children}</span>;

const requirements = [
  { id: 'PC-001', text: 'The controller shall start the pump when the tank level reaches the high setpoint.', cat: 'Functional', ver: ['ok', 'Verified L3'], state: ['ok', 'Approved'], tests: '1 test' },
  { id: 'PC-002', text: 'The controller shall stop the pump within 500 ms of a dry-run signal.', cat: 'Safety', ver: ['bad', 'Failed'], state: ['ok', 'Approved'], tests: '1 test' },
  { id: 'PC-003', text: 'Discharge pressure shall stay within 2 percent of the setpoint at steady state.', cat: 'Performance', ver: ['muted', 'Not verified'], state: ['ok', 'Approved'], tests: '1 test' },
  { id: 'PC-004', text: 'The controller shall record every alarm with its time and source.', cat: 'Functional', ver: ['muted', 'Not verified'], state: ['warn', 'In review'], tests: '1 test' },
  { id: 'PC-005', text: 'The controller shall report pump state to the supervisory system once per second.', cat: 'Interface', ver: ['ok', 'Verified L2'], state: ['ok', 'Approved'], tests: '2 tests' },
  { id: 'PC-006', text: 'Setpoints shall be changeable only from an authenticated service session.', cat: 'Security', ver: ['muted', 'Not verified'], state: ['muted', 'Draft'], tests: 'No test' },
];

const Rail = () => (
  <div className="rl-rail" aria-hidden="true">
    <span /><FiHome /><FiAlignLeft data-on="" /><FiCheck /><FiLayers /><FiBookOpen />
  </div>
);

function ProductScreen() {
  return (
    <div className="rl-screen" role="img" aria-label="The RMS Requirements screen for a pump controller project. A bar shows the project and the Browse, Trace and Flow tabs. Filter chips count 24 requirements by state. Six requirement rows each show an identifier, the statement, its category, a verification result and its state: five Approved or In review, one Draft, with one verified at level 3, one verified at level 2, one failing and three not yet verified.">
      <div className="rl-screen-in" aria-hidden="true">
        <Rail />
        <div className="rl-screen-main">
          <div className="rl-bar">
            <span className="rl-crumb">Pump controller <FiChevronDown /></span>
            <span className="rl-tabs"><span data-on="">Browse</span><span>Trace</span><span>Flow</span></span>
            <span className="rl-bar-end"><span className="rl-search"><FiSearch /> Search</span><span className="rl-new">New requirement</span></span>
          </div>
          <div className="rl-filters">
            <Chip on n={24}>All</Chip><Chip n={3}>Draft</Chip><Chip n={4}>In review</Chip><Chip n={15}>Approved</Chip><Chip n={1}>Rejected</Chip><Chip n={1}>Superseded</Chip>
          </div>
          <ul className="rl-reqs">
            {requirements.map((r) => (
              <li key={r.id} className="rl-req">
                <Id>{r.id}</Id>
                <div className="rl-req-main"><p>{r.text}</p><small>{r.cat}</small></div>
                <div className="rl-req-ver"><Pill tone={r.ver[0]}>{r.ver[1]}</Pill><small>{r.tests}</small></div>
                <div className="rl-req-state"><Pill tone={r.state[0]}>{r.state[1]}</Pill></div>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

// Each capability: a heading, a sentence or two, and a drawn piece of the real screen. The drawn piece is hidden from
// assistive technology and carries one label for the whole fragment.
const Frag = ({ label, children }) => (
  <div className="rl-frag" role="img" aria-label={label}><div aria-hidden="true">{children}</div></div>
);

function ReviewFragment() {
  return (
    <Frag label="A requirement in review with Reject and Approve buttons, above the lifecycle Draft, In review, Approved.">
      <div className="rl-life"><Pill tone="muted">Draft</Pill><span className="rl-arrow">to</span><Pill tone="warn">In review</Pill><span className="rl-arrow">to</span><Pill tone="ok">Approved</Pill></div>
      <div className="rl-detail">
        <div className="rl-detail-head"><Id>PC-004</Id><Pill tone="warn">In review</Pill><span className="rl-muted">Rev 2</span></div>
        <p className="rl-detail-text">The controller shall record every alarm with its time and source.</p>
        <div className="rl-btns"><span className="rl-btn">Reject</span><span className="rl-btn" data-primary="">Approve</span></div>
        <p className="rl-hint">Read the statement and criteria, then approve or reject.</p>
      </div>
      <div className="rl-note">Changing the statement or criteria of an approved requirement starts the next revision as a draft. The approved revision stays in its history.</div>
    </Frag>
  );
}

function TraceFragment() {
  const rows = [
    ['PC-001', 'ok', 'Approved', 'PC-000', 'TC-PC-001', ['ok', 'Pass'], 'UC-PC-001'],
    ['PC-002', 'ok', 'Approved', 'PC-000', 'TC-PC-002', ['bad', 'Fail'], 'UC-PC-001'],
    ['PC-003', 'ok', 'Approved', 'PC-000', null, null, null],
  ];
  return (
    <Frag label="The Trace screen: filter chips for gaps, then three requirements with the requirement they refine, their test cases with the latest result, and their use cases.">
      <div className="rl-filters rl-filters-flush">
        <Chip on n={15}>Everything</Chip><Chip n={2}>No test case</Chip><Chip n={4}>Failing tests</Chip><Chip n={1}>Tests to re-check</Chip><Chip n={0}>Unconnected</Chip>
      </div>
      <ul className="rl-trace">
        {rows.map(([id, tone, state, refines, tc, res, uc]) => (
          <li key={id}>
            <div><Id>{id}</Id> <Pill tone={tone}>{state}</Pill></div>
            <div><small>Refines</small><Id>{refines}</Id></div>
            <div><small>Test case</small>{tc ? <><Id>{tc}</Id> <Pill tone={res[0]}>{res[1]}</Pill></> : <span className="rl-gap">None yet</span>}</div>
            <div><small>Use case</small>{uc ? <Id>{uc}</Id> : <span className="rl-muted">Not linked</span>}</div>
          </li>
        ))}
      </ul>
    </Frag>
  );
}

function VerificationFragment() {
  const rows = [
    ['TC-PC-001', 'Verify PC-001', 'for PC-001 · Test · L2–L3 · mandatory', ['ok', 'Pass']],
    ['TC-PC-002', 'Verify PC-002', 'for PC-002 · Test · L2–L3 · mandatory', ['bad', 'Fail']],
    ['TC-PC-003', 'Verify PC-003', 'for PC-003 · Test · L2–L3 · mandatory', ['muted', 'Not verified']],
  ];
  return (
    <Frag label="The Verification screen: filter chips by result and three test cases with their latest result, Pass, Fail and Not verified, and a link to the recorded evidence.">
      <div className="rl-filters rl-filters-flush"><Chip on n={9}>All</Chip><Chip n={5}>Pass</Chip><Chip n={2}>Fail</Chip><Chip n={2}>Not verified</Chip></div>
      <ul className="rl-cases">
        {rows.map(([id, title, meta, pill]) => (
          <li key={id}>
            <Id>{id}</Id>
            <div><p>{title}</p><small>{meta}</small>{pill[1] === 'Pass' && <small className="rl-link">Open evidence</small>}</div>
            <Pill tone={pill[0]}>{pill[1]}</Pill>
          </li>
        ))}
      </ul>
    </Frag>
  );
}

function BaselineFragment() {
  return (
    <Frag label="The Baselines screen: two frozen baselines. PC-v1.0 with 15 requirements matches the live specification. PC-v1.1 with 18 requirements has 2 changed since freeze.">
      <ul className="rl-baselines">
        <li><Id>PC-v1.0</Id><strong>Pump controller v1.0 specification</strong><span className="rl-muted">15 requirements</span><Pill tone="ok">Frozen</Pill><span className="rl-ok">Matches the live specification</span></li>
        <li><Id>PC-v1.1</Id><strong>Pump controller v1.1 specification</strong><span className="rl-muted">18 requirements</span><Pill tone="ok">Frozen</Pill><span className="rl-warn">2 changed since freeze</span></li>
      </ul>
    </Frag>
  );
}

function AgentsFragment() {
  return (
    <Frag label="Agent connections and exchange: a connector URL to copy, a history entry made by an agent with its reason, and a ReqIF export to a partner tool.">
      <div className="rl-two">
        <div className="rl-box">
          <h3>Connect an agent</h3>
          <small>Connector URL</small>
          <div className="rl-copy"><code>https://rms.example.net/mcp</code><span className="rl-btn">Copy</span></div>
          <div className="rl-hist"><Pill tone="muted">Agent</Pill><span>Linked PC-002 to TC-PC-002</span></div>
          <p className="rl-reason">“The dry-run limit had no test case.”</p>
        </div>
        <div className="rl-box">
          <h3>Send to a partner tool</h3>
          <small>Format</small>
          <div className="rl-field">.reqifz (zipped, recommended)</div>
          <small>Who is this for?</small>
          <div className="rl-field">Supplier engineering team</div>
          <span className="rl-btn" data-primary="">Export</span>
        </div>
      </div>
    </Frag>
  );
}

const Service = ({ name, on, open }) => (
  <span className={`rl-service${on ? ' is-on' : ''}`}><span className="rl-service-name">{name}{open ? ' ' : ''}</span><i className="rl-switch" /></span>
);

function ServiceSwitch() {
  return (
    <Frag label="A project row in a workspace with two services, Stream and RMS, each with a switch, both turned on.">
      <div className="rl-project">
        <h3 translate="no">Pump controller</h3>
        <div className="rl-services"><Service name="Stream" on /><Service name="RMS" on /></div>
      </div>
      <div className="rl-project">
        <h3 translate="no">Test bench</h3>
        <div className="rl-services"><Service name="Stream" on /><Service name="RMS" /></div>
      </div>
    </Frag>
  );
}

const capabilities = [
  { id: 'review', h: 'Review and approval', p: 'Requirements move from Draft to In review to Approved, and each change to the wording is a new revision. The person who decides sees the statement and approves or rejects it.', Frag: ReviewFragment },
  { id: 'trace', h: 'Traceability', p: 'Link requirements to the requirements they refine, to test cases and to use cases. The gaps are listed: requirements without a test case, failing tests, links to re-check.', Frag: TraceFragment },
  { id: 'verification', h: 'Verification', p: 'Test cases have recorded results with evidence. A requirement counts as verified only when its tests pass at the level you set as the target.', Frag: VerificationFragment },
  { id: 'baselines', h: 'Baselines', p: 'Freeze the approved requirements as a reference, then compare it with the live specification later and see what changed.', Frag: BaselineFragment },
  { id: 'agents', h: 'AI agents and partner tools', p: 'AI agents work in RMS through MCP, with the access you approve, and every change they make is recorded with a reason. Exchange requirements and test cases with partner tools as ReqIF files.', Frag: AgentsFragment },
];

export default function RmsLanding() {
  return (
    <main className="rl-page">
      <Seo
        title="Plotune RMS: Requirements You Can Review, Trace and Verify"
        description="Plotune RMS keeps requirements with revisions, review and approval, traceability, test evidence and baselines in the same workspace as your projects. AI agents work through MCP, and ReqIF moves data to partner tools."
        path="/rms"
      />
      <div className="design-container">
        <header className="lx-shero rl-hero">
          <div>
            <h1>Requirements you can review, trace and verify, in the same workspace as your projects.</h1>
            <p className="lx-lead-left">Plotune RMS keeps each requirement with its revisions, its reviewers, its test cases and the evidence that it was checked.</p>
            <div className="lx-actions lx-actions-left">
              <Link className="design-button" to="/register">Create a workspace</Link>
              <Link className="design-button secondary" to="/login?next=/rms">Open RMS</Link>
            </div>
          </div>
          <div className="rl-hero-art art-ground">
            <Art name="knots-to-bridge" priority alt="Two engineers pull a knot of rope apart while a screen shows the tangle becoming a bridge." />
          </div>
        </header>

        <section className="rl-product" aria-label="RMS requirements screen">
          <ProductScreen />
        </section>

        {capabilities.map(({ id, h, p, Frag: Fragment }, i) => (
          <section key={id} className={`lx-section rl-cap${i % 2 ? ' rl-cap-flip' : ''}`} aria-labelledby={`rl-${id}`}>
            <div className="rl-cap-text"><h2 id={`rl-${id}`}>{h}</h2><p>{p}</p></div>
            <Fragment />
          </section>
        ))}

        <section className="lx-section rl-cap rl-workspace" aria-labelledby="rl-workspace">
          <div className="rl-cap-text">
            <h2 id="rl-workspace">Part of your workspace</h2>
            <p>RMS is switched on per project in a workspace, next to Stream. Turn it on for the projects that need it, turn it off when they do not.</p>
            <Link className="lx-inline" to="/stream">See Stream</Link>
          </div>
          <div className="rl-workspace-side">
            <ServiceSwitch />
            <div className="art-ground rl-art-small">
              <Art name="misfit-part" alt="An engineer holds up a puzzle piece that does not fit while a tall reviewer leans in to look at the gap." />
            </div>
          </div>
        </section>

        <section className="lx-closing">
          <h2>Start with a workspace.</h2>
          <p>Create one, add a project and switch RMS on for it.</p>
          <div className="lx-actions">
            <Link className="design-button" to="/register">Create a workspace</Link>
            <Link className="design-button secondary" to="/docs">Read the docs</Link>
            <Link className="design-button secondary" to="/contact">Talk to us</Link>
          </div>
        </section>
        <div className="lx-bottom" />
      </div>
    </main>
  );
}
